<?php

declare(strict_types=1);

use PrivacyFirst\ServerLogAnalytics\Config;
use PrivacyFirst\ServerLogAnalytics\DashboardRepository;
use PrivacyFirst\ServerLogAnalytics\Database;
use PrivacyFirst\ServerLogAnalytics\ImportState;
use PrivacyFirst\ServerLogAnalytics\LoginLimiter;
use PrivacyFirst\ServerLogAnalytics\RouteCatalog;

if (!defined('PRIVACY_LOG_ANALYTICS_ENTRY')) { http_response_code(404); exit; }
require __DIR__ . '/src/Analytics.php';
header('Content-Type: text/html; charset=UTF-8');
header('Cache-Control: no-store, max-age=0'); header('Pragma: no-cache');
header("Content-Security-Policy: default-src 'none'; style-src 'self'; form-action 'self'; frame-ancestors 'none'; base-uri 'none'");
header('Referrer-Policy: no-referrer'); header('X-Content-Type-Options: nosniff'); header('X-Frame-Options: DENY');
header('Permissions-Policy: camera=(), microphone=(), geolocation=(), browsing-topics=()');
if (($_SERVER['HTTPS'] ?? '') !== 'on' && ($_SERVER['HTTPS'] ?? '') !== '1') { http_response_code(403); exit('HTTPS is required.'); }
$documentRoot = $_SERVER['DOCUMENT_ROOT'] ?? ''; if ($documentRoot === '') throw new RuntimeException('DocumentRoot is unavailable.');
$config = Config::load(__DIR__ . '/config.php'); $config->assertPrivatePathsOutside($documentRoot);
$locale = $config->get('locale') === 'ja' ? 'ja' : 'en'; $copy = strings($locale);
$routes = RouteCatalog::load((string) $config->get('route_manifest'), (string) $config->get('site_prefix'));
Database::ensurePrivateDirectory((string) $config->get('session_path'));
ini_set('session.use_strict_mode', '1'); ini_set('session.use_only_cookies', '1'); ini_set('session.use_trans_sid', '0'); ini_set('session.cookie_httponly', '1'); ini_set('session.cookie_secure', '1'); ini_set('session.cookie_samesite', 'Strict'); ini_set('session.gc_maxlifetime', (string) $config->get('session_ttl_seconds'));
session_name('__SecurePrivacyLogAnalytics'); session_save_path((string) $config->get('session_path'));
session_set_cookie_params(['lifetime' => 0, 'path' => (string) $config->get('admin_cookie_path'), 'secure' => true, 'httponly' => true, 'samesite' => 'Strict']); session_start();
$now = time(); $ttl = (int) $config->get('session_ttl_seconds');
if (isset($_SESSION['last_activity']) && $now - (int) $_SESSION['last_activity'] > $ttl) { $_SESSION = []; session_destroy(); session_start(); }
$_SESSION['last_activity'] = $now; $_SESSION['csrf'] ??= bin2hex(random_bytes(32));
$limiter = new LoginLimiter((string) $config->get('login_lock_path'), (int) $config->get('login_window_seconds'), (int) $config->get('login_max_failures'), (int) $config->get('login_lock_seconds'));
$method = $_SERVER['REQUEST_METHOD'] ?? 'GET'; $action = is_string($_POST['action'] ?? null) ? $_POST['action'] : ''; $errorMessage = null;
if ($method === 'POST' && $action === 'login') {
    $check = $limiter->check(); $password = is_string($_POST['password'] ?? null) ? $_POST['password'] : ''; $csrf = is_string($_POST['csrf'] ?? null) ? $_POST['csrf'] : '';
    if (!hash_equals((string) $_SESSION['csrf'], $csrf)) { http_response_code(400); $errorMessage = $copy['reload']; }
    elseif (!$check['allowed']) { http_response_code(429); header('Retry-After: ' . $check['retry_after']); $errorMessage = $copy['limited']; }
    elseif (strlen($password) > 1024 || !password_verify($password, (string) $config->get('password_hash'))) { $limiter->recordFailure(); usleep(random_int(200000, 450000)); $errorMessage = $copy['login_failed']; }
    else { $limiter->reset(); session_regenerate_id(true); $_SESSION['authenticated'] = true; $_SESSION['last_activity'] = $now; $_SESSION['csrf'] = bin2hex(random_bytes(32)); header('Location: ./', true, 303); exit; }
}
if ($method === 'POST' && $action === 'logout') { $csrf = is_string($_POST['csrf'] ?? null) ? $_POST['csrf'] : ''; if (!hash_equals((string) $_SESSION['csrf'], $csrf)) { http_response_code(400); exit('Invalid request.'); } $_SESSION = []; session_destroy(); header('Location: ./', true, 303); exit; }
if (($_SESSION['authenticated'] ?? false) !== true) { renderLogin($copy, (string) $_SESSION['csrf'], $errorMessage, $locale); exit; }
$range = is_string($_GET['range'] ?? null) ? $_GET['range'] : '30'; if (!in_array($range, ['7', '30', '90', 'month'], true)) $range = '30';
$scale = is_string($_GET['scale'] ?? null) ? $_GET['scale'] : 'medium'; if (!in_array($scale, ['small', 'medium', 'large'], true)) $scale = 'medium';
$timezone = new DateTimeZone((string) $config->get('timezone')); $today = new DateTimeImmutable('today', $timezone); $start = $range === 'month' ? new DateTimeImmutable($today->format('Y-m-01'), $timezone) : $today->sub(new DateInterval('P' . ((int) $range - 1) . 'D')); $startDate = $start->format('Y-m-d'); $endDate = $today->format('Y-m-d');
$database = new Database($config); $repository = new DashboardRepository($database->pdo()); $totals = $repository->totals($startDate, $endDate); $series = $repository->series($startDate, $endDate); $monthlyStart = $today->modify('first day of this month')->sub(new DateInterval('P23M'))->format('Y-m'); $monthlySeries = $repository->monthlySeries($monthlyStart, $today->format('Y-m'));
$dimensions = []; foreach (['page', 'referrer', 'device', 'browser', 'os', 'status', 'not_found_category'] as $dimension) $dimensions[$dimension] = $repository->topDimension($dimension, $startDate, $endDate);
$latestImport = $repository->latestImport(); $importState = (new ImportState((string) $config->get('import_state_path')))->read();
renderDashboard($copy, $routes, (string) $_SESSION['csrf'], $range, $scale, $startDate, $endDate, $totals, $series, $monthlySeries, $dimensions, $latestImport, $importState, (int) $config->get('stale_after_hours'), $locale);

function e(string $value): string { return htmlspecialchars($value, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'); }
/** @return array<string,string> */
function strings(string $locale): array {
    $ja = ['title'=>'プライバシー重視サーバーログ分析','dashboard'=>'改善ダッシュボード','intro'=>'見られているページや改善が必要な入口を、最小限の集計から確認します。','password'=>'管理者パスワード','login'=>'ログイン','logout'=>'ログアウト','reload'=>'画面を再読み込みして、もう一度お試しください。','limited'=>'認証試行が一時的に制限されています。時間を置いてお試しください。','login_failed'=>'認証できませんでした。','session_note'=>'このCookieは管理者認証だけに使われ、訪問者の解析には使用されません。','range'=>'見る期間','update'=>'表示を更新','size'=>'文字の大きさ','small'=>'小','medium'=>'標準','large'=>'大','pv'=>'見られたページ','pv_note'=>'ページを開いた回数（PV）','not_found'=>'見つからないページ','not_found_note'=>'リンク切れなどの確認候補','bots'=>'自動アクセス','bots_note'=>'検索エンジンなどのBot','requests'=>'通常のアクセス','requests_note'=>'Bot以外の対象サイトへのリクエスト','daily'=>'日ごとの変化','daily_note'=>'ページが見られた回数の推移です。','monthly'=>'月ごとの変化','monthly_note'=>'長い目でページ閲覧数の変化を確認できます。','pages'=>'よく見られているページ','pages_note'=>'内容づくりや導線改善のヒントになります。','referrers'=>'どこから来たか','referrers_note'=>'外部サイト、直接アクセス、サイト内からの移動です。','devices'=>'使われた端末','devices_note'=>'PC・スマホなどの大まかな内訳です。','browsers'=>'使われたブラウザ','browsers_note'=>'表示確認の優先順位を考える目安です。','os'=>'使われたOS','os_note'=>'見た目の確認を優先する端末環境の目安です。','status'=>'アクセス結果','status_note'=>'200は正常、404は見つからない状態です。','missing'=>'見つからないものの種類','missing_note'=>'URLそのものは保存せず、種類だけを集計しています。','health'=>'取込の状態','health_note'=>'自動集計が動いているかを確認します。','ok'=>'取込は正常','stale'=>'取込が停止している可能性','failed'=>'直近の取込が失敗','last_import'=>'最終取込','site_rows'=>'対象サイト','none'=>'記録なし','privacy'=>'訪問者数・セッション数・個別リクエストは保存または表示していません。','item'=>'項目','count'=>'件数','no_data'=>'データがありません。','internal'=>'サイト内のページから','direct'=>'直接アクセス（ブックマーク・URL入力など）','invalid'=>'参照元を判別できないアクセス','external_other'=>'外部サイト（その他）','other_browser'=>'その他のブラウザ','other_os'=>'その他のOS','ios'=>'iPhone・iPad（iOS）','asset'=>'画像・CSS・JavaScriptなどのファイル','endpoint'=>'ページ・機能のURL'];
    if ($locale === 'ja') return $ja;
    return ['title'=>'Privacy-first Server Log Analytics','dashboard'=>'Improvement dashboard','intro'=>'Use minimum aggregated data to find popular pages and routes that may need attention.','password'=>'Administrator password','login'=>'Sign in','logout'=>'Sign out','reload'=>'Reload this page and try again.','limited'=>'Sign-in attempts are temporarily limited. Please try again later.','login_failed'=>'Unable to sign in.','session_note'=>'This cookie is used only for administrator authentication, never for visitor analytics.','range'=>'Period','update'=>'Update view','size'=>'Text size','small'=>'Small','medium'=>'Medium','large'=>'Large','pv'=>'Page views','pv_note'=>'Times a known page was opened','not_found'=>'Not found','not_found_note'=>'Possible broken links or missing files','bots'=>'Automated traffic','bots_note'=>'Search engines and other known bots','requests'=>'Regular requests','requests_note'=>'Target-site requests excluding bots','daily'=>'Daily change','daily_note'=>'How page views changed by day.','monthly'=>'Monthly change','monthly_note'=>'A longer view of page-view changes.','pages'=>'Popular pages','pages_note'=>'A clue for content and navigation improvements.','referrers'=>'Where people came from','referrers_note'=>'External sites, direct visits, or internal navigation.','devices'=>'Devices used','devices_note'=>'A broad PC, phone, and tablet breakdown.','browsers'=>'Browsers used','browsers_note'=>'A guide for visual-testing priorities.','os'=>'Operating systems used','os_note'=>'A guide for device environments to test.','status'=>'Request result','status_note'=>'200 means success; 404 means the page or file was not found.','missing'=>'Type of missing item','missing_note'=>'Only a safe category is stored, never the missing URL.','health'=>'Import health','health_note'=>'Whether scheduled aggregation is running.','ok'=>'Import is healthy','stale'=>'Import may have stopped','failed'=>'The latest import failed','last_import'=>'Latest import','site_rows'=>'target-site rows','none'=>'No record','privacy'=>'Visitor counts, sessions, and individual requests are neither stored nor shown.','item'=>'Item','count'=>'Count','no_data'=>'No data yet.','internal'=>'From a page on this site','direct'=>'Direct visit (bookmark or typed address)','invalid'=>'Referrer could not be classified','external_other'=>'External site (other)','other_browser'=>'Other browser','other_os'=>'Other operating system','ios'=>'iPhone or iPad (iOS)','asset'=>'Asset such as image, CSS, or JavaScript','endpoint'=>'Page or endpoint'];
}
/** @param array<string,string> $copy */
function renderLogin(array $copy, string $csrf, ?string $error, string $locale): void { ?>
<!doctype html><html lang="<?= e($locale) ?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= e($copy['title']) ?></title><link rel="stylesheet" href="./style.css"></head><body><main class="shell"><section class="panel login"><p class="eyebrow"><?= e($copy['title']) ?></p><h1><?= e($copy['dashboard']) ?></h1><p class="muted"><?= e($copy['intro']) ?></p><?php if ($error !== null): ?><p class="notice" role="alert"><?= e($error) ?></p><?php endif; ?><form method="post" action="./" autocomplete="off"><input type="hidden" name="action" value="login"><input type="hidden" name="csrf" value="<?= e($csrf) ?>"><label><?= e($copy['password']) ?><input type="password" name="password" required maxlength="1024" autocomplete="current-password"></label><button type="submit"><?= e($copy['login']) ?></button></form><p class="privacy-note"><?= e($copy['session_note']) ?></p></section></main></body></html>
<?php }
/** @param array<string,string> $copy @param array<string,int> $totals @param list<array<string,mixed>> $series @param list<array<string,mixed>> $monthlySeries @param array<string,list<array{value:string,count:int}>> $dimensions @param array<string,mixed>|null $latestImport @param array<string,mixed>|null $importState */
function renderDashboard(array $copy, RouteCatalog $routes, string $csrf, string $range, string $scale, string $start, string $end, array $totals, array $series, array $monthlySeries, array $dimensions, ?array $latestImport, ?array $importState, int $staleHours, string $locale): void { $latestAt = is_array($latestImport) ? strtotime((string) $latestImport['imported_at']) : false; $stateOk = ($importState['status'] ?? null) === 'ok'; $isStale = $latestAt === false || time() - $latestAt > $staleHours * 3600; $healthClass = !$stateOk ? 'bad' : ($isStale ? '' : 'ok'); $healthText = !$stateOk ? $copy['failed'] : ($isStale ? $copy['stale'] : $copy['ok']); ?>
<!doctype html><html lang="<?= e($locale) ?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= e($copy['dashboard']) ?> | <?= e($copy['title']) ?></title><link rel="stylesheet" href="./style.css"></head><body class="size-<?= e($scale) ?>"><main class="shell"><header class="topbar"><div><p class="eyebrow"><?= e($copy['title']) ?></p><h1><?= e($copy['dashboard']) ?></h1><p class="hero-copy"><?= e($copy['intro']) ?></p></div><form method="post" action="./"><input type="hidden" name="action" value="logout"><input type="hidden" name="csrf" value="<?= e($csrf) ?>"><button class="ghost" type="submit"><?= e($copy['logout']) ?></button></form></header><section class="panel filter-panel"><form class="filters" method="get" action="./"><label><?= e($copy['range']) ?><select name="range"><option value="7"<?= $range === '7' ? ' selected' : '' ?>><?= $locale === 'ja' ? '過去7日' : 'Last 7 days' ?></option><option value="30"<?= $range === '30' ? ' selected' : '' ?>><?= $locale === 'ja' ? '過去30日' : 'Last 30 days' ?></option><option value="90"<?= $range === '90' ? ' selected' : '' ?>><?= $locale === 'ja' ? '過去90日' : 'Last 90 days' ?></option><option value="month"<?= $range === 'month' ? ' selected' : '' ?>><?= $locale === 'ja' ? '今月' : 'This month' ?></option></select></label><input type="hidden" name="scale" value="<?= e($scale) ?>"><button type="submit"><?= e($copy['update']) ?></button><span class="muted"><?= e($start) ?> – <?= e($end) ?></span></form><nav class="scale-picker" aria-label="<?= e($copy['size']) ?>"><span><?= e($copy['size']) ?></span><?php foreach (['small','medium','large'] as $key): ?><a class="<?= $scale === $key ? 'is-current' : '' ?>" href="?range=<?= e($range) ?>&amp;scale=<?= e($key) ?>"<?= $scale === $key ? ' aria-current="page"' : '' ?>><?= e($copy[$key]) ?></a><?php endforeach; ?></nav></section><section class="metrics"><article class="metric metric--primary"><span><?= e($copy['pv']) ?></span><strong><?= number_format($totals['pageviews']) ?></strong><small><?= e($copy['pv_note']) ?></small></article><article class="metric"><span><?= e($copy['not_found']) ?></span><strong><?= number_format($totals['not_found']) ?></strong><small><?= e($copy['not_found_note']) ?></small></article><article class="metric"><span><?= e($copy['bots']) ?></span><strong><?= number_format($totals['bot_requests']) ?></strong><small><?= e($copy['bots_note']) ?></small></article><article class="metric"><span><?= e($copy['requests']) ?></span><strong><?= number_format($totals['requests']) ?></strong><small><?= e($copy['requests_note']) ?></small></article></section><section class="grid"><?php panel($copy['daily'],$copy['daily_note'],renderSeries($series,'',$copy)); panel($copy['monthly'],$copy['monthly_note'],renderSeries($monthlySeries,$locale === 'ja' ? '月' : '',$copy)); panel($copy['pages'],$copy['pages_note'],renderTable($dimensions['page'],fn(string $value): string => $routes->label($value),$copy)); panel($copy['referrers'],$copy['referrers_note'],renderTable($dimensions['referrer'],fn(string $value): string => displayReferrer($value,$copy),$copy)); panel($copy['devices'],$copy['devices_note'],renderTable($dimensions['device'],null,$copy)); panel($copy['browsers'],$copy['browsers_note'],renderTable($dimensions['browser'],fn(string $value): string => $value === 'Other' ? $copy['other_browser'] : $value,$copy)); panel($copy['os'],$copy['os_note'],renderTable($dimensions['os'],fn(string $value): string => displayOs($value,$copy),$copy)); panel($copy['status'],$copy['status_note'],renderTable($dimensions['status'],fn(string $value): string => displayStatus($value,$locale),$copy)); panel($copy['missing'],$copy['missing_note'],renderTable($dimensions['not_found_category'],fn(string $value): string => $value === 'static-asset' ? $copy['asset'] : $copy['endpoint'],$copy)); ?><article class="panel wide"><h2><?= e($copy['health']) ?></h2><p class="panel-help"><?= e($copy['health_note']) ?></p><div class="health"><span class="dot <?= e($healthClass) ?>"></span><strong><?= e($healthText) ?></strong></div><p class="muted"><?= e($copy['last_import']) ?>: <?= $latestImport ? e((string) $latestImport['imported_at']) . ' / ' . e($copy['site_rows']) . ' ' . number_format((int) $latestImport['site_rows']) : e($copy['none']) ?></p></article></section><p class="privacy-note"><?= e($copy['privacy']) ?></p></main></body></html>
<?php }
function panel(string $title,string $note,string $contents): void { echo '<article class="panel"><h2>'.e($title).'</h2><p class="panel-help">'.e($note).'</p>'.$contents.'</article>'; }
/** @param list<array<string,mixed>> $rows @param array<string,string> $copy */ function renderSeries(array $rows,string $suffix,array $copy): string { if ($rows===[]) return '<p class="muted">'.e($copy['no_data']).'</p>'; $max=max(1,max(array_map(fn(array $row):int=>(int)$row['pageviews'],$rows))); $html='<div class="bars">'; foreach($rows as $row) $html.='<div class="bar-row"><span>'.e((string)$row['period']).e($suffix).'</span><progress max="'.$max.'" value="'.(int)$row['pageviews'].'"></progress><strong>'.number_format((int)$row['pageviews']).'</strong></div>'; return $html.'</div>'; }
/** @param list<array{value:string,count:int}> $rows @param callable(string):string|null $labeler @param array<string,string> $copy */ function renderTable(array $rows,?callable $labeler,array $copy): string { if($rows===[]) return '<p class="muted">'.e($copy['no_data']).'</p>'; $html='<table><thead><tr><th>'.e($copy['item']).'</th><th>'.e($copy['count']).'</th></tr></thead><tbody>'; foreach($rows as $row){$label=$labeler?$labeler($row['value']):$row['value'];$html.='<tr><td>'.e($label).'</td><td>'.number_format($row['count']).'</td></tr>';}return $html.'</tbody></table>'; }
/** @param array<string,string> $copy */ function displayReferrer(string $value,array $copy): string { return match($value){'direct'=>$copy['direct'],'internal'=>$copy['internal'],'invalid'=>$copy['invalid'],'external:other'=>$copy['external_other'],default=>str_starts_with($value,'external:')?'External: '.substr($value,9):$value}; }
/** @param array<string,string> $copy */ function displayOs(string $value,array $copy): string { return match($value){'Other'=>$copy['other_os'],'iOS'=>$copy['ios'],default=>$value}; }
function displayStatus(string $value,string $locale): string { $ja=['200'=>'200: 正常に表示できた','206'=>'206: 一部だけ送信（動画・再開ダウンロード等）','301'=>'301: 新しいページへ案内した','304'=>'304: 更新なし（ブラウザの保存済み表示）','400'=>'400: アクセス内容を受け取れなかった','404'=>'404: ページやファイルが見つからない','429'=>'429: アクセスが多すぎて一時制限','500'=>'500: サーバー側のエラー'];$en=['200'=>'200: Displayed successfully','206'=>'206: Partial response (normal for media or resumed downloads)','301'=>'301: Moved permanently','304'=>'304: Browser may use its cached copy','400'=>'400: Invalid request','404'=>'404: Page or file not found','429'=>'429: Too many requests','500'=>'500: Server error'];return($locale==='ja'?$ja:$en)[$value]??'HTTP '.$value;}
